package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Every record the file holds, in file order (none while there is no file). */
    public synchronized List<String> lines() {
        try {
            return Files.exists(file)
                    ? Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList()
                    : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.audit;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * The audit viewer: the audit lines of a sheet exactly as the audit file holds them, newest first. Given a
 * name, only the lines about that person: those carrying {@code name=} or {@code person=} that name, compared
 * as names are (case and surrounding spaces ignored); the sheet's descendants' lines about them follow (each
 * sheet's newest first, the sheets in id order), then, when that person was transferred here, the sheet they
 * came from's lines about them, newest first. It reads the file; it records nothing.
 */
@RestController
@RequestMapping("/api/sheets/{sheetId}/audit")
@Validated
public class AuditController {

    /** A field of a line: its key, and its value running up to the next field (a value may hold spaces). */
    private static final Pattern FIELD = Pattern.compile("(?:^|\\s)([A-Za-z][\\w-]*)=(.*?)(?=\\s[A-Za-z][\\w-]*=|$)");

    private final Audit audit;
    private final PersonRepository people;
    private final SheetService sheets;

    public AuditController(Audit audit, PersonRepository people, SheetService sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    @GetMapping
    public List<String> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(required = false) String name) {
        String sheet = sheetId.trim();
        String who = name == null ? "" : name.strip().toLowerCase(Locale.ROOT);
        List<String> all = audit.lines();
        List<String> lines = about(all, sheet, who);
        if (!who.isEmpty()) {
            sheets.descendants(sheet).stream().sorted()
                    .forEach(descendant -> lines.addAll(about(all, descendant, who)));
            people.findBySheetIdAndNameIgnoreCase(sheet, name.strip()).map(Person::getOrigin)
                    .ifPresent(origin -> lines.addAll(about(all, origin, who)));
        }
        return lines;
    }

    /** The sheet's lines, newest first; given a name (lower-cased), only those about that person. */
    private static List<String> about(List<String> all, String sheet, String who) {
        List<String> lines = new ArrayList<>(all.stream()
                .filter(l -> carries(l, "sheet", sheet, false))
                .filter(l -> who.isEmpty() || carries(l, "name", who, true) || carries(l, "person", who, true))
                .toList());
        Collections.reverse(lines);
        return lines;
    }

    private static boolean carries(String line, String key, String value, boolean asName) {
        Matcher m = FIELD.matcher(line);
        while (m.find()) {
            if (!m.group(1).equals(key)) {
                continue;
            }
            String v = m.group(2);
            if (asName ? v.strip().toLowerCase(Locale.ROOT).equals(value) : v.equals(value)) {
                return true;
            }
        }
        return false;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit viewer: the sheet's audit lines exactly as the audit file holds them, newest first. With a name in
// the filter, only the lines about that person (name= or person= that name, case and surrounding spaces ignored),
// then those of the sheet's descendants and of the sheet the person came from.
// It reads the file; it records nothing.
@Component({
  selector: 'app-audit',
  template: `
    <section aria-label="Audit">
      <h2>Audit</h2>
      <form (submit)="show($event)" aria-label="Show audit">
        <label for="audit-filter">Person</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filter()"
          (input)="filter.set(value($event)); error.set('')"
        />
        <button type="submit" data-testid="audit-show">Show</button>
        @if (error()) {
          <p role="alert" data-testid="audit-error">{{ error() }}</p>
        }
      </form>
      <ol>
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class Audit {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly filter = signal('');
  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal('');
  /** Bumped on every press, so only the latest press's answer is shown. */
  private shows = 0;

  constructor() {
    effect(() => {
      this.session.sheet();
      this.session.loads();
      this.shows++;
      this.lines.set([]);
      this.error.set('');
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async show(e: Event): Promise<void> {
    e.preventDefault();
    const sheet = this.session.sheet();
    if (!sheet) return;
    const show = ++this.shows;
    this.lines.set([]);
    this.error.set('');
    try {
      const lines = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/audit`, { params: { name: this.filter() } }),
      );
      if (show === this.shows) this.lines.set(lines);
    } catch {
